mapper.update:
update sys_department set parent_id=#{parentId,jdbcType=BIGINT},code=#{code},name=#{name},
       sort_order=#{sortOrder},updated_by=#{operator}
where id=#{id} and deleted=0

mapper.select:
select parent.id from sys_permission child
join sys_permission parent on parent.code=child.parent_code
where child.id=#{id}
